LAYER
  NAME "t_rezago_educativo_porcentaje_analfabetismo"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, porcentaje_analfabetismo FROM rezago_educativo_estimacion_inea2025.tematico_indice_alfa) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Texto Mapa tematico de la estimación del rezago educativo INEA2025 (porcentaje_analfabetismo)"
    "wms_enable_request" "*"
  END
  LABELITEM "porcentaje_analfabetismo"
  CLASS
    NAME "bajo"
    EXPRESSION ([porcentaje_analfabetismo] <=7.54)
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "medio"
    EXPRESSION ([porcentaje_analfabetismo] >7.54 and [porcentaje_analfabetismo] <=11.0)
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "alto"
    EXPRESSION ([porcentaje_analfabetismo] >11.0 and [porcentaje_analfabetismo] <=15.14)
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "muy_alto"
    EXPRESSION ([porcentaje_analfabetismo] >15.14)
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
END

